const NAME = /^[A-Za-z0-9_.-]+$/

/** Parses the input text into { tasks: Map<name, cost BigInt>, deps: Map<name, sorted string[]> }. */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const tasks = new Map()
  const depSets = new Map()
  const used = []
  lines.forEach((raw, idx) => {
    const n = idx + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new GraphError(`error: line ${n}: expected task <name> <cost>`)
      if (!NAME.test(w[1])) throw new GraphError(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new GraphError(`error: line ${n}: cost must be a non-negative integer`)
      if (tasks.has(w[1])) throw new GraphError(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new GraphError(`error: line ${n}: expected dep <name> <dependency>...`)
      if (!depSets.has(w[1])) depSets.set(w[1], new Set())
      for (const d of w.slice(1)) used.push(d)
      for (const d of w.slice(2)) depSets.get(w[1]).add(d)
    } else {
      throw new GraphError(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const name of used) {
    if (!tasks.has(name)) throw new GraphError(`error: unknown task ${name}`)
  }
  const deps = new Map()
  for (const name of tasks.keys()) deps.set(name, [...(depSets.get(name) ?? [])].sort())
  return { tasks, deps }
}
"}

